import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { REPO_ROOT } from '../helpers';
import { runIn } from './run-in';

const BUILT_CLI = path.join(REPO_ROOT, 'packages/cli/dist/bin.js');

/**
 * The Prisma client of a generated project and the schema of its test database, build products its
 * sources read: generated by its own `db:client`, with the dependencies of the workspace, lent to the
 * project for the time of the command. The script names the kit by its binary, which the build of
 * the workspace writes without the right to be run when it comes from an artifact: a launcher of the
 * built CLI stands first in the PATH.
 */
export function generatePrismaClient(root: string): void {
  const lent = path.join(root, 'node_modules');
  const launchers = fs.mkdtempSync(path.join(os.tmpdir(), 'ddd-ts-kit-launcher-'));

  fs.symlinkSync(path.join(REPO_ROOT, 'node_modules'), lent, 'dir');
  fs.writeFileSync(path.join(launchers, 'ddd-ts-kit'), `#!/bin/sh\nexec node "${BUILT_CLI}" "$@"\n`, { mode: 0o755 });

  try {
    runIn(root, {
      command: 'npm',
      args: ['run', '--silent', 'db:client'],
      env: { PATH: `${launchers}${path.delimiter}${process.env['PATH'] ?? ''}` },
    });
  } finally {
    fs.unlinkSync(lent);
    fs.rmSync(launchers, { recursive: true, force: true });
  }
}
